:root{--bg:#0f1720;--panel:#17222f;--line:#263546;--text:#e8eef5;--mute:#8da0b4;--accent:#4aa3ff;--good:#3ecf8e;--bad:#ff7a6b}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
.wrap{max-width:1120px;margin:0 auto;padding:48px 32px 40px}
header{margin-bottom:36px;border-bottom:1px solid var(--line);padding-bottom:24px}
h1{margin:0;font-size:40px;line-height:1.1;letter-spacing:-.02em}
.sub{margin:6px 0 0;color:var(--mute);font-size:18px}
section{margin-bottom:40px}
h2{margin:0 0 16px;font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:var(--mute);font-weight:600}
.tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.tile{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:20px 22px}
.tile .label{color:var(--mute);font-size:14px}
.tile .val{font-size:40px;font-weight:700;margin:6px 0 4px;font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.tile .val small{font-size:20px;font-weight:500;color:var(--mute);margin-left:4px}
.tile .chg{font-size:14px;font-weight:600;font-variant-numeric:tabular-nums}
.tile .chg span{color:var(--mute);font-weight:400}
.good{color:var(--good)}.bad{color:var(--bad)}
table{width:100%;border-collapse:collapse;background:var(--panel);border:1px solid var(--line);border-radius:10px;overflow:hidden;font-variant-numeric:tabular-nums}
th,td{padding:12px 22px;text-align:right;border-bottom:1px solid var(--line)}
th:first-child,td:first-child{text-align:left}
th{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--mute);font-weight:600;background:#1b2a3a}
td{font-size:18px}
td:first-child{font-weight:600}
tr:last-child td{border-bottom:0}
.bars{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:12px 22px}
.row{display:grid;grid-template-columns:120px 1fr 90px;align-items:center;gap:20px;padding:10px 0}
.row .n{font-weight:600;font-size:18px}
.row .v{text-align:right;font-variant-numeric:tabular-nums;font-size:18px}
.track{height:18px;background:#101a24;border-radius:4px}
.fill{height:100%;background:linear-gradient(90deg,#2b7fd6,var(--accent));border-radius:4px}
footer{color:var(--mute);font-size:14px;border-top:1px solid var(--line);padding-top:20px}
@media(max-width:800px){.tiles{grid-template-columns:repeat(2,1fr)}}
@media(max-width:480px){.tiles{grid-template-columns:1fr}.wrap{padding:28px 16px}th,td{padding:10px 12px}}

